/**
 * Make untrusted text safe to write to a terminal. Kept in the CLI so basic
 * commands do not install the optional full-screen OpenTUI monitor.
 *
 * @param {unknown} value
 * @param {{ preserveSgr?: boolean }} [options]
 */
declare function sanitizeTerminalText(value: unknown, options?: {
    preserveSgr?: boolean;
}): string;

export { sanitizeTerminalText };
